"""Story verification — automated HA checks after agent run."""

from __future__ import annotations

import asyncio
import re
from typing import TYPE_CHECKING, Any

import httpx

if TYPE_CHECKING:
    from fastmcp import Client


async def _retry(fn, attempts: int = 3, delay: float = 2.0) -> Any | None:
    """Call fn() up to `attempts` times, returning first non-None result."""
    for i in range(attempts):
        result = await fn()
        if result is not None:
            return result
        if i < attempts - 1:
            await asyncio.sleep(delay)
    return None


# ---------------------------------------------------------------------------
# State checks — use /api/states (REST, with retry for HA registration lag)
# ---------------------------------------------------------------------------


async def _check_entity_exists(client: httpx.AsyncClient, check: dict) -> dict:
    entity_id = check["entity_id"]

    async def attempt():
        r = await client.get(f"/api/states/{entity_id}")
        if r.status_code == 200:
            return {"passed": True, "detail": f"Found {entity_id}"}
        return None

    result = await _retry(attempt)
    if result is not None:
        return {**check, "type": "entity_exists", **result}
    return {
        **check,
        "type": "entity_exists",
        "passed": False,
        "detail": f"{entity_id} not found",
    }


async def _check_entity_state(client: httpx.AsyncClient, check: dict) -> dict:
    entity_id = check["entity_id"]
    expected = check["state"]

    async def attempt():
        r = await client.get(f"/api/states/{entity_id}")
        if r.status_code == 200 and r.json().get("state") == expected:
            return {"passed": True, "detail": f"state={expected}"}
        return None

    result = await _retry(attempt)
    if result is not None:
        return {**check, "type": "entity_state", **result}

    # Diagnostic read to get current actual state for error reporting.
    r = await client.get(f"/api/states/{entity_id}")
    try:
        actual = r.json().get("state") if r.status_code == 200 else "not found"
    except Exception:
        actual = "not found"
    return {
        **check,
        "type": "entity_state",
        "passed": False,
        "detail": f"expected={expected}, actual={actual}",
    }


async def _find_in_states(
    client: httpx.AsyncClient, domain: str, alias: str
) -> dict | None:
    """Search /api/states for entity in domain whose friendly_name contains alias. Returns state dict or None."""
    r = await client.get("/api/states")
    if r.status_code != 200:
        return None
    try:
        states = r.json()
    except Exception:
        return None
    for state in states:
        if state["entity_id"].startswith(f"{domain}."):
            name = state["attributes"].get("friendly_name", "")
            if alias.lower() in name.lower():
                return state
    return None


async def _check_domain_entity_exists(
    client: httpx.AsyncClient, check: dict, domain: str, check_type: str
) -> dict:
    alias = check["alias"]

    async def attempt():
        state = await _find_in_states(client, domain, alias)
        if state:
            return {"passed": True, "detail": f"Found {state['entity_id']}"}
        return None

    result = await _retry(attempt)
    if result is not None:
        return {**check, "type": check_type, **result}
    return {
        **check,
        "type": check_type,
        "passed": False,
        "detail": f"No {domain} matching '{alias}'",
    }


async def _check_automation_exists(client: httpx.AsyncClient, check: dict) -> dict:
    return await _check_domain_entity_exists(
        client, check, "automation", "automation_exists"
    )


async def _check_script_exists(client: httpx.AsyncClient, check: dict) -> dict:
    return await _check_domain_entity_exists(client, check, "script", "script_exists")


# ---------------------------------------------------------------------------
# Config checks — use /api/config/automation/config (REST, no retry)
# ---------------------------------------------------------------------------


async def _find_in_automation_config(
    client: httpx.AsyncClient, alias: str
) -> dict | None:
    """Return the automation config dict whose alias matches, or None."""
    # Find entity via states; unique_id is in the 'id' attribute of the same state dict.
    state = await _find_in_states(client, "automation", alias)
    if not state:
        return None
    unique_id = state.get("attributes", {}).get("id")
    if not unique_id:
        return None
    r = await client.get(f"/api/config/automation/config/{unique_id}")
    if r.status_code != 200:
        return None
    try:
        return r.json()
    except Exception:
        return None


async def _check_automation_has_condition(
    client: httpx.AsyncClient, check: dict
) -> dict:
    alias = check["alias"]
    auto = await _find_in_automation_config(client, alias)
    if auto is None:
        return {
            **check,
            "type": "automation_has_condition",
            "passed": False,
            "detail": f"Automation '{alias}' not found",
        }
    conditions = auto.get("condition", auto.get("conditions", []))
    if conditions:
        return {
            **check,
            "type": "automation_has_condition",
            "passed": True,
            "detail": f"{len(conditions)} condition(s)",
        }
    return {
        **check,
        "type": "automation_has_condition",
        "passed": False,
        "detail": "No conditions found",
    }


async def _check_automation_has_trigger(client: httpx.AsyncClient, check: dict) -> dict:
    alias = check["alias"]
    auto = await _find_in_automation_config(client, alias)
    if auto is None:
        return {
            **check,
            "type": "automation_has_trigger",
            "passed": False,
            "detail": f"Automation '{alias}' not found",
        }
    triggers = auto.get("trigger", auto.get("triggers", []))
    if triggers:
        return {
            **check,
            "type": "automation_has_trigger",
            "passed": True,
            "detail": f"{len(triggers)} trigger(s)",
        }
    return {
        **check,
        "type": "automation_has_trigger",
        "passed": False,
        "detail": "No triggers found",
    }


# ---------------------------------------------------------------------------
# Registry / dashboard checks — use shared in-process MCP client
# ---------------------------------------------------------------------------


async def _mcp_call(mcp_client, tool_name: str, args: dict | None = None) -> str:
    """Call an MCP tool and return concatenated text output."""
    result = await mcp_client.call_tool(tool_name, args or {})
    return "\n".join(block.text for block in result.content if hasattr(block, "text"))


async def _check_area_exists(mcp_client, check: dict) -> dict:
    name = check["name"]
    try:
        text = await _mcp_call(mcp_client, "ha_list_floors_areas")
        if name.lower() in text.lower():
            return {
                **check,
                "type": "area_exists",
                "passed": True,
                "detail": f"Found area '{name}'",
            }
    except Exception as e:
        return {
            **check,
            "type": "area_exists",
            "passed": False,
            "detail": f"Error: {e}",
        }
    return {
        **check,
        "type": "area_exists",
        "passed": False,
        "detail": f"Area '{name}' not found",
    }


async def _check_label_exists(mcp_client, check: dict) -> dict:
    name = check["name"]
    try:
        text = await _mcp_call(mcp_client, "ha_config_get_label")
        if name.lower() in text.lower():
            return {
                **check,
                "type": "label_exists",
                "passed": True,
                "detail": f"Found label '{name}'",
            }
    except Exception as e:
        return {
            **check,
            "type": "label_exists",
            "passed": False,
            "detail": f"Error: {e}",
        }
    return {
        **check,
        "type": "label_exists",
        "passed": False,
        "detail": f"Label '{name}' not found",
    }


async def _check_dashboard_exists(mcp_client, check: dict) -> dict:
    url_path = check["url_path"]
    try:
        text = await _mcp_call(
            mcp_client, "ha_config_get_dashboard", {"list_only": True}
        )
        if url_path in text:
            return {
                **check,
                "type": "dashboard_exists",
                "passed": True,
                "detail": f"Found dashboard '{url_path}'",
            }
    except Exception as e:
        return {
            **check,
            "type": "dashboard_exists",
            "passed": False,
            "detail": f"Error: {e}",
        }
    return {
        **check,
        "type": "dashboard_exists",
        "passed": False,
        "detail": f"No dashboard with url_path='{url_path}'",
    }


# ---------------------------------------------------------------------------
# Response checks — string/regex on agent output (no HA call needed)
# ---------------------------------------------------------------------------


def _check_response_contains(check: dict, agent_output: str) -> dict:
    value = check["value"]
    if value.lower() in agent_output.lower():
        return {
            **check,
            "type": "response_contains",
            "passed": True,
            "detail": f"Found '{value}'",
        }
    return {
        **check,
        "type": "response_contains",
        "passed": False,
        "detail": f"'{value}' not in response",
    }


def _check_response_contains_any(check: dict, agent_output: str) -> dict:
    values = check["values"]
    if isinstance(values, str):
        values = [values]
    output_lower = agent_output.lower()
    matched = next((v for v in values if v.lower() in output_lower), None)
    if matched:
        return {
            **check,
            "type": "response_contains_any",
            "passed": True,
            "detail": f"Found '{matched}'",
        }
    return {
        **check,
        "type": "response_contains_any",
        "passed": False,
        "detail": f"None of {values!r} found in response",
    }


def _check_response_matches(check: dict, agent_output: str) -> dict:
    pattern = check["pattern"]
    if re.search(pattern, agent_output):
        return {
            **check,
            "type": "response_matches",
            "passed": True,
            "detail": f"Pattern matched: {pattern}",
        }
    return {
        **check,
        "type": "response_matches",
        "passed": False,
        "detail": f"Pattern not matched: {pattern}",
    }


# ---------------------------------------------------------------------------
# Check registries
# ---------------------------------------------------------------------------

SYNC_CHECKS = {
    "entity_exists": _check_entity_exists,
    "entity_state": _check_entity_state,
    "automation_exists": _check_automation_exists,
    "script_exists": _check_script_exists,
    "automation_has_condition": _check_automation_has_condition,
    "automation_has_trigger": _check_automation_has_trigger,
}

ASYNC_CHECKS = {
    "area_exists": _check_area_exists,
    "label_exists": _check_label_exists,
    "dashboard_exists": _check_dashboard_exists,
}

RESPONSE_CHECKS = {
    "response_contains": _check_response_contains,
    "response_contains_any": _check_response_contains_any,
    "response_matches": _check_response_matches,
}


# ---------------------------------------------------------------------------
# Public entry point
# ---------------------------------------------------------------------------


async def verify_ha_checks(
    ha_url: str,
    ha_token: str,
    checks: list[dict],
    agent_output: str,
    mcp_client: Client,
) -> list[dict]:
    """Run all checks concurrently and return results list [{type, passed, detail, ...}].

    Caller owns the ``mcp_client`` lifecycle so one in-process server can be
    shared across many verify_ha_checks calls.
    """
    headers = {"Authorization": f"Bearer {ha_token}"}

    async def run_check(check: dict, http) -> dict:
        check_type = check["type"]
        if check_type in SYNC_CHECKS:
            return await SYNC_CHECKS[check_type](http, check)
        if check_type in ASYNC_CHECKS:
            return await ASYNC_CHECKS[check_type](mcp_client, check)
        if check_type in RESPONSE_CHECKS:
            return RESPONSE_CHECKS[check_type](check, agent_output)
        return {**check, "passed": False, "detail": f"Unknown check type: {check_type}"}

    async with httpx.AsyncClient(base_url=ha_url, headers=headers, timeout=10) as http:
        return list(await asyncio.gather(*[run_check(c, http) for c in checks]))

"""Unit tests for verify_story.py."""

from __future__ import annotations

import asyncio
import importlib.util
from pathlib import Path
from unittest.mock import AsyncMock, MagicMock, patch

import httpx

SCRIPT = Path(__file__).resolve().parent / "scripts" / "verify_story.py"
spec = importlib.util.spec_from_file_location("verify_story", str(SCRIPT))
verify_story = importlib.util.module_from_spec(spec)
spec.loader.exec_module(verify_story)


def _run(coro):
    return asyncio.run(coro)


def _mock_response(status_code: int, json_data):
    r = MagicMock()
    r.status_code = status_code
    r.json.return_value = json_data
    return r


def _mock_client(response_or_fn):
    """AsyncMock httpx client. Accepts a fixed response or an async side-effect function."""
    client = AsyncMock(spec=httpx.AsyncClient)
    if asyncio.iscoroutinefunction(response_or_fn):
        client.get.side_effect = response_or_fn
    else:
        client.get.return_value = response_or_fn
    return client


HA_URL = "http://localhost:9999"
HA_TOKEN = "test-token"


class TestEntityExists:
    def test_found(self):
        client = _mock_client(_mock_response(200, {"state": "on"}))
        result = _run(
            verify_story._check_entity_exists(
                client, {"type": "entity_exists", "entity_id": "light.test"}
            )
        )
        assert result["passed"] is True

    def test_not_found(self):
        client = _mock_client(_mock_response(404, {}))
        with patch("asyncio.sleep", new_callable=AsyncMock):
            result = _run(
                verify_story._check_entity_exists(
                    client, {"type": "entity_exists", "entity_id": "light.missing"}
                )
            )
        assert result["passed"] is False
        assert "not found" in result["detail"]


class TestEntityState:
    def test_state_matches(self):
        client = _mock_client(_mock_response(200, {"state": "on"}))
        result = _run(
            verify_story._check_entity_state(
                client,
                {"type": "entity_state", "entity_id": "automation.test", "state": "on"},
            )
        )
        assert result["passed"] is True

    def test_state_mismatch(self):
        # 3 retry attempts + 1 diagnostic call = 4 total
        off = _mock_response(200, {"state": "off"})
        client = AsyncMock(spec=httpx.AsyncClient)
        client.get.side_effect = [off, off, off, off]
        with patch("asyncio.sleep", new_callable=AsyncMock):
            result = _run(
                verify_story._check_entity_state(
                    client,
                    {
                        "type": "entity_state",
                        "entity_id": "automation.test",
                        "state": "on",
                    },
                )
            )
        assert result["passed"] is False
        assert "expected=on" in result["detail"]
        assert "actual=off" in result["detail"]


class TestAutomationExists:
    def test_found_by_friendly_name(self):
        states = [
            {
                "entity_id": "automation.sunset_porch_light",
                "attributes": {"friendly_name": "Sunset Porch Light"},
            }
        ]
        client = _mock_client(_mock_response(200, states))
        result = _run(
            verify_story._check_automation_exists(
                client, {"type": "automation_exists", "alias": "Sunset Porch Light"}
            )
        )
        assert result["passed"] is True
        assert "automation.sunset_porch_light" in result["detail"]

    def test_not_found(self):
        client = _mock_client(_mock_response(200, []))
        with patch("asyncio.sleep", new_callable=AsyncMock):
            result = _run(
                verify_story._check_automation_exists(
                    client, {"type": "automation_exists", "alias": "Missing"}
                )
            )
        assert result["passed"] is False


class TestAutomationHasCondition:
    def _make_client(self, condition):
        states = [
            {
                "entity_id": "automation.evening_lights_test",
                "attributes": {"friendly_name": "Evening Lights Test", "id": "abc123"},
            }
        ]
        config = {
            "alias": "Evening Lights Test",
            "condition": condition,
            "trigger": [{"platform": "time"}],
        }

        async def mock_get(path, **kwargs):
            if "/api/config/automation/config/" in path:
                return _mock_response(200, config)
            return _mock_response(200, states)

        return _mock_client(mock_get)

    def test_has_condition(self):
        client = self._make_client(
            [
                {
                    "condition": "state",
                    "entity_id": "input_boolean.someone_home",
                    "state": "on",
                }
            ]
        )
        result = _run(
            verify_story._check_automation_has_condition(
                client,
                {"type": "automation_has_condition", "alias": "Evening Lights Test"},
            )
        )
        assert result["passed"] is True
        assert "1 condition" in result["detail"]

    def test_no_condition(self):
        client = self._make_client([])
        result = _run(
            verify_story._check_automation_has_condition(
                client,
                {"type": "automation_has_condition", "alias": "Evening Lights Test"},
            )
        )
        assert result["passed"] is False
        assert "No conditions" in result["detail"]


class TestResponseChecks:
    def test_response_contains_found(self):
        result = verify_story._check_response_contains(
            {"type": "response_contains", "value": "light.bed_light"},
            "I found light.bed_light in your system",
        )
        assert result["passed"] is True

    def test_response_contains_not_found(self):
        result = verify_story._check_response_contains(
            {"type": "response_contains", "value": "light.bed_light"},
            "I found nothing",
        )
        assert result["passed"] is False

    def test_response_contains_any_case_insensitive(self):
        result = verify_story._check_response_contains_any(
            {
                "type": "response_contains_any",
                "values": ["Bed Light Evening", "bed_light_evening"],
            },
            "Found automation.bed_light_evening in your config",
        )
        assert result["passed"] is True
        assert "bed_light_evening" in result["detail"]

    def test_response_contains_any_string_coerced_to_list(self):
        # YAML misconfiguration: values: "automation" (str) instead of values: ["automation"].
        # Without the isinstance guard, iterating over the string's characters would match
        # 't', 'o', 'n' etc. in "the light is on" — a false positive.
        result = verify_story._check_response_contains_any(
            {"type": "response_contains_any", "values": "automation"},
            "The light is on",
        )
        assert result["passed"] is False

    def test_response_contains_any_none_match(self):
        result = verify_story._check_response_contains_any(
            {"type": "response_contains_any", "values": ["automation", "logbook"]},
            "The light was off the whole time",
        )
        assert result["passed"] is False
        assert "None of" in result["detail"]

    def test_response_matches_regex(self):
        result = verify_story._check_response_matches(
            {"type": "response_matches", "pattern": r"\b6\b"},
            "I found 6 lights in total",
        )
        assert result["passed"] is True
